// Handle install template
if (isset($_POST['install_template']) && isset($templates[$_POST['template_key']])) {
    csrf_verify();
    $key = $_POST['template_key'];
    $tpl = $templates[$key];

    // Create flow
    $stmt_cf = $conn->prepare("INSERT INTO chatbot_flows (company_id, name, trigger_keyword, trigger_type, is_active) VALUES (?,?,?,'keyword',1)");
    $stmt_cf->bind_param("iss", $companyId, $tpl['name'], $tpl['trigger']);
    $stmt_cf->execute();
    $flowId = $stmt_cf->insert_id;

    // Create nodes
    $nodeIds = [];
    foreach ($tpl['nodes'] as $i => $n) {
        [$type,$label,$msg,$next,$btns,$saveAs] = array_pad($n, 6, null);
        $btnJson = $btns ? json_encode(array_map(fn($b)=>['label'=>$b,'next_node_id'=>null],$btns)) : null;
        $stmt_cn = $conn->prepare("INSERT INTO chatbot_nodes (flow_id, node_type, label, message_text, button_options, save_response_as) VALUES (?,?,?,?,?,?)");
        $stmt_cn->bind_param("isssss", $flowId, $type, $label, $msg, $btnJson, $saveAs);
        $stmt_cn->execute();
        $nodeIds[] = $stmt_cn->insert_id;
    }
    // Link nodes sequentially (simple chain for now)
    for ($i=0; $i<count($nodeIds)-1; $i++) {
        $nid = $nodeIds[$i]; $nextId = $nodeIds[$i+1];
        $conn->prepare("UPDATE chatbot_nodes SET next_node_id=? WHERE id=?")->bind_param("ii",$nextId,$nid) && $conn->prepare("UPDATE chatbot_nodes SET next_node_id=? WHERE id=?")->execute();
        $stmt_lnk = $conn->prepare("UPDATE chatbot_nodes SET next_node_id=? WHERE id=?");
        $stmt_lnk->bind_param("ii", $nextId, $nid);
        $stmt_lnk->execute();
    }
    header("Location: chatbot_builder.php?flow_id=$flowId&msg=installed");
    exit();
}

